<!doctype html><html lang="es"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans;color:#163b32}.ticket{margin:20px;padding:22px;border:2px solid #163b32}.head{padding:15px;background:#10352f;color:#fff}.grid{display:table;width:100%;margin-top:14px}.cell{display:table-cell;width:33%;padding:10px;border:1px solid #dce8e3}.label{color:#648078;font-size:9px;text-transform:uppercase}.qr{display:table;width:100%;margin-top:16px}.qr div{display:table-cell;vertical-align:middle}.qr img{width:120px}.break{page-break-after:always}</style></head><body>@php($isAir=$reservation->isAir()) @php($trip=$isAir?$reservation->airDeparture:$reservation->departure) @php($route=$isAir?$trip->airRoute:$trip->transportRoute) @php($vehicle=$isAir?$trip->aircraft:$trip->vessel) @php($company=$vehicle->organization)
@foreach($reservation->seats as $seat)@if($seat->ticket)@php($ticket=$seat->ticket)<div class="head"><h1>NavegaYA · Boleto {{$isAir?'aéreo':'fluvial'}}</h1><p>Reserva {{$reservation->code}} · Boleto {{$ticket->code}}</p></div><main class="ticket"><h2>{{$seat->passenger_name}}</h2><strong>DNI {{$seat->document_number}}</strong><div class="grid"><div class="cell"><span class="label">Origen</span><br>{{$isAir?$route->origin_city:$route->originPort->city}}</div><div class="cell"><span class="label">Destino</span><br>{{$isAir?$route->destination_city:$route->destinationPort->city}}</div><div class="cell"><span class="label">Salida</span><br>{{$trip->departure_at->format('d/m/Y H:i')}}</div></div><div class="grid"><div class="cell"><span class="label">Empresa / RUC</span><br>{{$company->commercial_name ?: $company->legal_name}}<br>{{$company->ruc}}</div><div class="cell"><span class="label">{{$isAir?'Aeronave':'Embarcación'}}</span><br>{{$vehicle->name}}</div><div class="cell"><span class="label">Asiento</span><br>{{$isAir?$seat->aircraftSeat->code:$seat->seat->code}}</div></div><div class="qr"><div style="width:140px"><img src="{{$qrDataUris[$ticket->id]}}"></div><div><strong>Presenta este QR al abordar.</strong><br>{{$ticket->boarding_token}}</div></div></main><div class="break"></div>@endif @endforeach</body></html>
